"use strict";exports.classifyRequestError=function(s={}){const e=Number(s.statusCode||s.code),n=String(s.errMsg||s.message||s.msg||"");return n.includes("timeout")?{kind:"timeout",message:"请求超时，请稍后重试"}:n.includes("network")?{kind:"network",message:"网络连接失败，请检查网络"}:401===e?{kind:"auth",message:"登录已超时，请重新登录"}:403===e?{kind:"permission",message:s.msg||"暂无操作权限"}:e>=400&&e<500?{kind:"validation",message:s.msg||"提交内容有误"}:e>=500?{kind:"server",message:"服务暂时不可用"}:{kind:"unknown",message:s.msg||"请求失败"}};
